import{_ as e,o as r,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Active Benchmarking RGW","description":"","frontmatter":{"title":"Active Benchmarking RGW","date":"2026-07-09T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["RGW","性能优化","监控","对象存储","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Active_Benchmarking_RGW.md","filePath":"posts/2026/Active_Benchmarking_RGW.md","lastUpdated":null}'),o={name:"posts/2026/Active_Benchmarking_RGW.md"};function n(l,t,s,c,h,d){return r(),a("div",null,[...t[0]||(t[0]=[i('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本文是 Marcel 在 Ceph 社区的一次闪电演讲，主题是&quot;Active Benchmarking RGW&quot;——即如何在 RGW（RADOS Gateway）基准测试运行期间实时分析性能表现，而非事后分析结果。</p><h2 id="什么是-active-benchmarking" tabindex="-1">什么是 Active Benchmarking <a class="header-anchor" href="#什么是-active-benchmarking" aria-label="Permalink to &quot;什么是 Active Benchmarking&quot;">​</a></h2><p>Marcel 引用了 Brendan Gregg 网站上对 active benchmarking 的定义：在基准测试运行期间，同时使用其他工具分析性能，而不是等测试结束后才查看结果。他进一步扩展了这个概念——理想情况下，所有数据都汇聚到同一个 dashboard 中，做到实时可视化。</p><p>这样做的核心目标是：<strong>避免被基准测试结果所欺骗</strong>。当基准测试工具输出的数据与系统自身上报的 metrics 能够相互印证时，结论才更可信。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p>Marcel 使用的工具栈包含三个部分：</p><p><strong>系统被测对象（System Under Test）</strong></p><ul><li>RGW（RADOS Gateway）</li></ul><p><strong>负载生成器</strong></p><ul><li><strong>k6</strong>：由 Grafana 开发的负载测试框架。与 FIO、s3bench 等内置 workload 的工具不同，k6 是一个框架，用户使用 JavaScript 编写测试逻辑，灵活性更高。</li></ul><p><strong>可观测性栈</strong></p><ul><li><strong>Prometheus + Grafana</strong>：标准的 metrics 采集与可视化方案</li><li><strong>cAdvisor</strong>：容器级别的资源监控</li><li><strong>mtail</strong>：日志转 Prometheus metrics 的瑞士军刀工具，通过配置规则解析 RGW access log，提取延迟数据、状态码、user agent 等信息，生成 histogram metrics</li></ul><h2 id="k6-的核心能力" tabindex="-1">k6 的核心能力 <a class="header-anchor" href="#k6-的核心能力" aria-label="Permalink to &quot;k6 的核心能力&quot;">​</a></h2><ol><li><p><strong>灵活的 workload 定义</strong>：用 JavaScript 编写，可模拟复杂业务流程（登录、创建对象等）。对于 S3 操作，需要自行实现 AWS Signature 签名认证逻辑（官方 S3 library 性能特性不佳，不推荐使用）。</p></li><li><p><strong>丰富的测试场景配置</strong>：</p><ul><li>恒定 IOPS 模式（如持续 200 IOPS）</li><li>breakpoint 测试（从低负载逐步提升，直到 P99 超过 200ms 或错误率上升时自动停止）</li></ul></li><li><p><strong>HTTP 层深度 instrumentation</strong>：内置对 TLS 握手时间、TTFB（Time to First Byte）等各阶段延迟的 histogram 采集。</p></li><li><p><strong>Kubernetes 扩展</strong>：提供 Kubernetes Operator，可通过 node selector 将 workload 分发到多个节点，适用于大规模集群测试。</p></li><li><p><strong>实时数据推送</strong>：支持在测试运行期间通过 remote write 将 metrics 实时写入 Prometheus，并支持 native histogram。</p></li></ol><h2 id="测试示例分析" tabindex="-1">测试示例分析 <a class="header-anchor" href="#测试示例分析" aria-label="Permalink to &quot;测试示例分析&quot;">​</a></h2><p>测试在 Marcel 的笔记本上运行，分为三个阶段：</p><table tabindex="0"><thead><tr><th>阶段</th><th>描述</th></tr></thead><tbody><tr><td>轻负载</td><td>系统正常，延迟集中且分布紧凑</td></tr><tr><td>边界负载</td><td>系统开始出现少量错误，延迟扩散至 250ms 区域</td></tr><tr><td>饱和</td><td>操作耗时接近 1 分钟，系统完全过载</td></tr></tbody></table><p><strong>关键观测点</strong>：</p><ul><li>饱和阶段的延迟看似&quot;变快&quot;，实际是因为系统快速返回错误响应（微秒级），而非正常处理请求。</li><li>RGW 内部 <code>req</code> 指标（in-flight requests）超过 1024 限制后，系统开始拒绝请求。</li><li>通过 mtail 解析 RGW 日志，可以看到 HTTP 503 状态码以及 RGW 内部错误码（如 <code>-2</code>、<code>-28</code> 表示过载）的分布情况。</li></ul><p><strong>Flame Graph 对比</strong>：k6 侧与 RGW 日志侧的延迟 histogram 可以相互对照验证，两者观测到的行为一致，增强了测试结论的可信度。</p><h2 id="核心结论与建议" tabindex="-1">核心结论与建议 <a class="header-anchor" href="#核心结论与建议" aria-label="Permalink to &quot;核心结论与建议&quot;">​</a></h2><ol><li><p><strong>实时观测的价值</strong>：在找到系统可持续处理速率后，保持负载运行，同时进行调整操作（如重启 OSD），实时观察 latency 变化，能更直观地理解系统行为。</p></li><li><p><strong>平均值会掩盖真相（Averages Hide the Truth）</strong>：建议优先关注 P99、latency histogram 火焰图等分布型指标，而非平均响应时间。</p></li><li><p><strong>未来展望</strong>：目前通过 mtail 解析日志来获取细粒度数据是一种变通方案，理想情况下这些 metrics 应该直接内置到 RGW 中。</p></li></ol><h2 id="工具参考" tabindex="-1">工具参考 <a class="header-anchor" href="#工具参考" aria-label="Permalink to &quot;工具参考&quot;">​</a></h2><ul><li><strong>k6</strong>：<a href="https://k6.io/" target="_blank" rel="noreferrer">grafana/k6</a> — JavaScript 驱动的负载测试框架</li><li><strong>mtail</strong>：Google 开源的日志转 metrics 工具，语法类似 AWK</li></ul>',25)])])}const m=e(o,[["render",n]]);export{p as __pageData,m as default};
